FROM users u



WHERE u.id = #{employeeId}

SELECT id
FROM departments

WHERE id = #{departmentId}
AND company_id = #{companyId}
AND status = 1

FOR SHARE

SELECT id
FROM positions

WHERE id = #{positionId}
AND company_id = #{companyId}
AND status = 1

